old_remove = '''        const Pipe pipe = pipes[index];\n        std::cout << pipe.start << '\\n' << std::flush;\n        pipes[index].active = false;\n        fenwickAdd(static_cast<int>(index), -1);\n        --activePipeCount;\n        addFreeGap(pipe.start, pipe.start + pipe.length, pipe.sizeCohort);'''
new_remove = '''        const Pipe pipe = pipes[index];\n        std::cout << pipe.start << '\\n' << std::flush;\n        recordLifetime(pipe.length, placementCount - pipe.bornPlacement);\n        pipes[index].active = false;\n        fenwickAdd(static_cast<int>(index), -1);\n        --activePipeCount;\n        liveLength -= pipe.length;\n        addFreeGap(pipe.start, pipe.start + pipe.length, pipe.sizeCohort);\n        recordNearNewest(rankPermille);'''
